QL_SECTION='<section class="section soft" id="library"><div class="wrap"><div class="section-heading"><p class="eyebrow">THE QUOTE LIBRARY</p><h2>Every line worth keeping.</h2></div><div class="ql-lead"><p>We interview the people you name, on your floor. The library is everything usable that comes out of those conversations: every line transcribed, attributed, and tagged by theme, by audience, and by what it is good for.</p><p>Your writers pull from it for the length of the campaign. It is not a transcript to scrub through. <strong>It is proof, sorted.</strong></p></div><p class="ql-demo-lead"><strong>Here is a real one.</strong> Memorial Health’s emergency department campaign produced fifty-seven quotes from seven speakers. Pick what you are writing, then open a line to see everywhere it works.</p><div class="ql-filters" role="group" aria-label="Filter quotes by what you are writing"><button type="button" data-ql="all" aria-pressed="true">Everything <span>10</span></button><button type="button" data-ql="film" aria-pressed="false">The hero film <span>5</span></button><button type="button" data-ql="email" aria-pressed="false">A donor email <span>6</span></button><button type="button" data-ql="social" aria-pressed="false">A social post <span>5</span></button><button type="button" data-ql="board" aria-pressed="false">A board or major gift ask <span>4</span></button></div><p class="ql-count" aria-live="polite">Showing all 10 quotes in this sample</p><div class="tw ql-wrap"><table class="ql-table"><caption class="sr-only">Sample quote library, filterable by use</caption><thead><tr><th scope="col">Quote</th><th scope="col">Speaker</th><th scope="col">Theme</th><th scope="col">Length</th></tr></thead><tbody><tr class="ql-row" data-tags="film email social"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd1"><span class="ql-mark" aria-hidden="true"></span>“The service that my family received on that day, the support and the comfort that I received from the people that knew me, it was not because I am someone special, but it\'s because Memorial Hospital is some place special.”</button></td><td class="ql-sp"><strong>Pastor Joseph Ray</strong><span>Methodist Pastor, Richwood</span></td><td><span class="ql-theme">Community ownership</span></td><td class="ql-len">Medium</td></tr><tr class="ql-detail" id="qd1" data-tags="film email social" hidden><td colspan="4"><div><p><span>Best audience</span>Community and grassroots donors, general public</p><p><span>Works in</span>Hero film · Donor email · Social · Landing page</p></div></td></tr><tr class="ql-row" data-tags="email board"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd2"><span class="ql-mark" aria-hidden="true"></span>“A community owned hospital that is present and involved and engaged in the way that Memorial is in our community and solicits and asks for the community to be a part of it is very uncommon. It\'s very rare.”</button></td><td class="ql-sp"><strong>Adam Hodnichak</strong><span>Executive Director, Union County Foundation</span></td><td><span class="ql-theme">Community ownership</span></td><td class="ql-len">Medium</td></tr><tr class="ql-detail" id="qd2" data-tags="email board" hidden><td colspan="4"><div><p><span>Best audience</span>Major donors, board, community donors</p><p><span>Works in</span>Donor email · Board update · Major gift appeal</p></div></td></tr><tr class="ql-row" data-tags="email social film"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd3"><span class="ql-mark" aria-hidden="true"></span>“It was started right here by the farmers and businesses that are local. When I come to the hospital, I might run into somebody I know. In fact, almost every time I come to the hospital, I run into people I know.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Community ownership</span></td><td class="ql-len">Long</td></tr><tr class="ql-detail" id="qd3" data-tags="email social film" hidden><td colspan="4"><div><p><span>Best audience</span>Community donors, grassroots</p><p><span>Works in</span>Donor email · Social · Video</p></div></td></tr><tr class="ql-row" data-tags="board"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd4"><span class="ql-mark" aria-hidden="true"></span>“This is a regional health system that started out as a community hospital. It\'s run and operated locally. The decisions are all made here. I think we want to keep it that way.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Community ownership</span></td><td class="ql-len">Short</td></tr><tr class="ql-detail" id="qd4" data-tags="board" hidden><td colspan="4"><div><p><span>Best audience</span>Major donors, corporate donors</p><p><span>Works in</span>Major gift conversation · Board update</p></div></td></tr><tr class="ql-row" data-tags="film social"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd5"><span class="ql-mark" aria-hidden="true"></span>“Here at Memorial we see the emergency department as the front door to the hospital, and Memorial is the backbone of the community.”</button></td><td class="ql-sp"><strong>Spence Fisher</strong><span>President, Memorial Health</span></td><td><span class="ql-theme">Front door</span></td><td class="ql-len">Short</td></tr><tr class="ql-detail" id="qd5" data-tags="film social" hidden><td colspan="4"><div><p><span>Best audience</span>All audiences</p><p><span>Works in</span>Video · Social · Landing page · Pull quote</p></div></td></tr><tr class="ql-row" data-tags="social email"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd6"><span class="ql-mark" aria-hidden="true"></span>“As the community grows, so does demand. The time is now.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Urgency of now</span></td><td class="ql-len">Short</td></tr><tr class="ql-detail" id="qd6" data-tags="social email" hidden><td colspan="4"><div><p><span>Best audience</span>All audiences</p><p><span>Works in</span>Social · Video graphic · Email subject line</p></div></td></tr><tr class="ql-row" data-tags="social film"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd7"><span class="ql-mark" aria-hidden="true"></span>“Our region\'s not getting any smaller, it\'s getting much larger, and we need to be able to meet that need.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Urgency of now</span></td><td class="ql-len">Short</td></tr><tr class="ql-detail" id="qd7" data-tags="social film" hidden><td colspan="4"><div><p><span>Best audience</span>All audiences</p><p><span>Works in</span>Short video soundbite · Social</p></div></td></tr><tr class="ql-row" data-tags="email film"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd8"><span class="ql-mark" aria-hidden="true"></span>“I\'ve been in the community since 1987, and since then the population has more than doubled. Probably two and a half times what it was then. If you really think about it, the hospital needs to expand to meet that growth.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Urgency of now</span></td><td class="ql-len">Medium</td></tr><tr class="ql-detail" id="qd8" data-tags="email film" hidden><td colspan="4"><div><p><span>Best audience</span>Community donors, corporate donors</p><p><span>Works in</span>Donor email · Video</p></div></td></tr><tr class="ql-row" data-tags="email board"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd9"><span class="ql-mark" aria-hidden="true"></span>“If we didn\'t build new lines or consider the infrastructure requirements with new substations, then we definitely couldn\'t keep up. So we don\'t want to wait until the lights are going out.”</button></td><td class="ql-sp"><strong>Anthony Smith</strong><span>CEO, URE and Foundation Board</span></td><td><span class="ql-theme">Urgency of now</span></td><td class="ql-len">Medium</td></tr><tr class="ql-detail" id="qd9" data-tags="email board" hidden><td colspan="4"><div><p><span>Best audience</span>Corporate and employer donors</p><p><span>Works in</span>Business donor outreach · Thought leadership</p></div></td></tr><tr class="ql-row" data-tags="board"><td class="ql-q"><button type="button" aria-expanded="false" aria-controls="qd10"><span class="ql-mark" aria-hidden="true"></span>“We want to make sure we\'re being proactive and creating enough space for the future as opposed to just reacting to issues when they occur.”</button></td><td class="ql-sp"><strong>Spence Fisher</strong><span>President, Memorial Health</span></td><td><span class="ql-theme">Urgency of now</span></td><td class="ql-len">Short</td></tr><tr class="ql-detail" id="qd10" data-tags="board" hidden><td colspan="4"><div><p><span>Best audience</span>Major donors, board</p><p><span>Works in</span>Board deck · Leadership narrative</p></div></td></tr></tbody></table></div><p class="ql-foot">Fifty-seven of these came out of one interview day. The case statement, the gala script, the donor letter and the job post all draw from the same place.</p></div></section>'
QL_JS='<script>(function(){var bs=[].slice.call(document.querySelectorAll(".ql-filters button")),rows=[].slice.call(document.querySelectorAll(".ql-row")),c=document.querySelector(".ql-count");function close_(r){var b=r.querySelector("button"),d=document.getElementById(b.getAttribute("aria-controls"));b.setAttribute("aria-expanded","false");if(d)d.hidden=true;}function pick(k,label){var n=0;rows.forEach(function(r){var on=k==="all"||(" "+r.dataset.tags+" ").indexOf(" "+k+" ")>-1;r.hidden=!on;if(!on)close_(r);else n++;});bs.forEach(function(b){b.setAttribute("aria-pressed",b.dataset.ql===k?"true":"false");});c.textContent=k==="all"?("Showing all "+n+" quotes in this sample"):("Showing "+n+" of "+rows.length+" for "+label.toLowerCase());}bs.forEach(function(b){b.addEventListener("click",function(){pick(b.dataset.ql,b.textContent.replace(/\\s*\\d+\\s*$/,"").trim());});});rows.forEach(function(r){var b=r.querySelector("button");b.addEventListener("click",function(){var d=document.getElementById(b.getAttribute("aria-controls")),open=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",open?"false":"true");if(d)d.hidden=open;});});})();</script>'
